import jsPDF from "jspdf";

var muktaRegular = "";
var muktaBold = "";

var callAddFont = function () {
  this.addFileToVFS("Mukta-Regular.ttf", muktaRegular);
  this.addFont("Mukta-Regular.ttf", "Mukta", "normal");

  this.addFileToVFS("Mukta-Bold.ttf", muktaBold);
  this.addFont("Mukta-Bold.ttf", "Mukta", "bold");
};

jsPDF.API.events.push(["addFonts", callAddFont]);